import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  stat_data: z.object({
    '{{user}}': z.object({
      心跳: z.coerce.number().prefault(75),
      羞耻度: z.coerce.number().prefault(0),
      暴露风险: z.coerce.number().prefault(0),
      当前着装: z.string().prefault('圣玛丽亚学院夏季制服')
    }).prefault({ 心跳: 75, 羞耻度: 0, 暴露风险: 0, 当前着装: '圣玛丽亚学院夏季制服' }),
    环境: z.object({
      当前时间: z.string().prefault('08:30 AM'),
      地点: z.string().prefault('学院正门'),
      氛围: z.string().prefault('樱花飞舞的开学日')
    }).prefault({ 当前时间: '08:30 AM', 地点: '学院正门', 氛围: '樱花飞舞的开学日' }),
    当前少女: z.object({
      姓名: z.string().prefault('未知'),
      情感状态: z.object({
        好感度: z.coerce.number().prefault(0).transform(value => _.clamp(value, 0, 100)),
        怀疑度: z.coerce.number().prefault(0)
      }).prefault({ 好感度: 0, 怀疑度: 0 }),
      生理状态: z.object({
        心跳: z.coerce.number().prefault(75),
        体温: z.coerce.number().prefault(36.5)
      }).prefault({ 心跳: 75, 体温: 36.5 }),
      服饰细节: z.object({
        上装: z.string().prefault('圣玛丽亚校服衬衫'),
        下装: z.string().prefault('百褶裙'),
        丝袜: z.string().prefault('null'),
        内衣: z.string().prefault('null')
      }).prefault({ 上装: '圣玛丽亚校服衬衫', 下装: '百褶裙', 丝袜: 'null', 内衣: 'null' })
    }).prefault({ 姓名: '未知', 情感状态: { 好感度: 0, 怀疑度: 0 }, 生理状态: { 心跳: 75, 体温: 36.5 }, 服饰细节: { 上装: '圣玛丽亚校服衬衫', 下装: '百褶裙', 丝袜: 'null', 内衣: 'null' } })
  }).prefault({ '{{user}}': { 心跳: 75, 羞耻度: 0, 暴露风险: 0, 当前着装: '圣玛丽亚学院夏季制服' }, 环境: { 当前时间: '08:30 AM', 地点: '学院正门', 氛围: '樱花飞舞的开学日' }, 当前少女: { 姓名: '未知', 情感状态: { 好感度: 0, 怀疑度: 0 }, 生理状态: { 心跳: 75, 体温: 36.5 }, 服饰细节: { 上装: '圣玛丽亚校服衬衫', 下装: '百褶裙', 丝袜: 'null', 内衣: 'null' } } })
});

$(() => {
  registerMvuSchema(Schema);
});
